local _, WFJ = ...
WFJ.Data.add("book", {
  ["3f5420eb13512f71"] = { "Con gli insettoidi cacciati in esilio, i due imperi troll tornarono alla vita di sempre. Nonostante la grande vittoria, nessuna delle due civiltà si espanse molto oltre i propri confini originari. Tuttavia, antichi testi parlano di una piccola fazione di troll che si staccò dall'Impero Amani e fondò una propria colonia nel cuore dell'oscuro continente.", "." },
  ["3f8f08fefc5e706b"] = { "⟦Stormwind=Roccavento⟧, e a quel punto le parcelle, i compensi e i salari della Gilda dei Tagliapietre rimasero non pagati e senza riscontro. Allora Edwin VanCleef era stato eletto maestro della Gilda dei Tagliapietre, e alzò la voce per esigere un risarcimento per le nostre opere. Per tutta risposta, la House of Nobles di ⟦Stormwind=Roccavento⟧ ordinò lo scioglimento della Gilda dei Tagliapietre, cosa che, comprensibilmente, fece infuriare VanCleef. Alla testa di una rivolta, VanCleef guidò i Tagliapietre fuori dalla città. Prima di proseguire, ci sono altri eventi avvenuti in", "." },
  ["3f91d242f4de5b76"] = { "Gli Shu'halo furono costretti ad abbandonare i loro possedimenti ancestrali e a vagare per sempre come nomadi nelle pianure sconfinate. Si diceva che un giorno la speranza sarebbe tornata e che le tribù disperse degli Shu'halo avrebbero trovato una nuova casa tra le braccia amorevoli della Madre Terra.", "." },
  ["3fb869ef92c314e3"] = { "Caro Martek,\n\nsono nei guai e mi serve il tuo aiuto.\n\nIo e mio fratello stiamo costruendo un'auto da corsa e ci servono pistoni robusti. Niente di quello che provo è abbastanza duro. Niente regge la velocità della nostra nuova auto. E così il motore si rompe di continuo!\n\nTu sei un esperto nella lavorazione dei metalli. Devi aiutarci. Sei l'unico che può farlo.", "." },
  ["3fc0704c9b96da1c"] = { "Tutto procede bene. Ho evocato un numero maggiore di worgen perché combattano al mio fianco. Benché siano di mente semplice, hanno dimostrato una notevole capacità di coordinare gli attacchi e di agire come gruppo.\n\nHo individuato dei capi nei loro branchi. A loro ho affidato il comando di piccoli gruppi di guerrieri. Colpiamo da molti punti della foresta contemporaneamente, e la mia campagna contro i demoni sta dando frutti.\n\nChe le benedizioni di Elune siano con me finché il mio lavoro non sarà compiuto.", "." },
  ["3fc38afbc2c86256"] = { "<Le pagine sono coperte di antiche rune elfiche.>\n\nQueste pagine contengono i ricordi degli eventi accaduti durante la raccolta e la creazione dei reagenti necessari a forgiare gli arcanum superiori.\n\nChe i nostri nemici non possano mai mettere le mani su questi libram.\n\nChe io possa vivere abbastanza da vedere di nuovo la pallida luce della luna splendere su Quel'Thalas.\n\nChe io possa morire, se non per grazia di Kael'thas.\n\nChe io possa uccidere per la gloria di Illidan.\n\n-Maestro Kariel Winthalus", "." },
})
